    private static string Html() => """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ornament · one concept, different constructions</title><style>
:root{--paper:#faf8ee;--ink:#263d4e;--muted:#667675;--line:#cccebf;--accent:#315f79}*{box-sizing:border-box}body{background:var(--paper);color:var(--ink);font:17px/1.5 system-ui,sans-serif;margin:0}main{max-width:1500px;margin:auto;padding:30px}h1,h2,h3{font:400 30px/1.2 Georgia,serif}h1{font-size:42px;max-width:1050px;margin:12px 0 20px}h3{font-size:22px;margin:8px 0}p{max-width:1070px}a{color:var(--accent)}.meta,.note{color:var(--muted);font-size:14px}.stats{display:flex;gap:20px;flex-wrap:wrap;border-block:1px solid var(--line);padding:14px 0;margin:25px 0}.stats strong{font-size:23px}.controls{display:grid;grid-template-columns:1.2fr 1.6fr 1fr;gap:16px}label{font-size:14px;color:var(--muted)}select,button{font:inherit;color:var(--ink);border:1px solid #aab5ad;border-radius:4px;background:#fffdf5;padding:9px;max-width:100%;cursor:pointer}select{display:block;width:100%;margin-top:7px}button:hover{background:#ecefe8}.source{display:grid;grid-template-columns:1.1fr 1fr;gap:25px;align-items:center;border:1px solid var(--line);background:#fffdf6;padding:18px;margin:24px 0}.source img{width:100%;display:block;aspect-ratio:2;object-fit:contain}.notice{padding:15px 18px;border-left:4px solid #8c8468;background:#eeecdf;margin:20px 0}.example-buttons{display:flex;flex-wrap:wrap;gap:10px;margin:15px 0}.example-buttons button{font-size:14px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{border:1px solid var(--line);background:#fffdf6;padding:15px;min-width:0;cursor:pointer}.card:hover{border-color:#527c87;box-shadow:0 2px 8px #263d4e12}.card img{display:block;width:100%;aspect-ratio:2;object-fit:contain;background:var(--paper)}.card p{font-size:14px;margin:8px 0}.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.chip{font-size:12px;background:#edf0e8;padding:4px 8px;border:1px solid #d5d8c8}.chip.comparison{background:#eceaf0}.chip.unknown{background:#f1eadc}.options{display:flex;gap:22px;align-items:center;flex-wrap:wrap;margin:20px 0}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;border-bottom:1px solid var(--line);padding:9px 12px}summary{cursor:pointer}details{border-block:1px solid var(--line);padding:16px 0;margin:25px 0}.inspection{margin:35px 0;padding:22px;border:1px solid var(--line);background:#fffdf6}.inspection .images{display:grid;grid-template-columns:1fr 1fr;gap:20px}.inspection img{width:100%;aspect-ratio:2;object-fit:contain}.pill{font:600 13px system-ui;padding:4px 8px;border:1px solid #9baea8;display:inline-block}.facts{display:flex;gap:18px;flex-wrap:wrap;font-size:14px;margin:20px 0}.empty{padding:25px;border:1px dashed var(--line)}.foot{font-size:14px;color:var(--muted);margin:30px 0}code{font-size:13px;overflow-wrap:anywhere}
@media(max-width:950px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.controls{grid-template-columns:1fr 1fr}.controls>label:first-child{grid-column:1/-1}}@media(max-width:620px){main{padding:17px}h1{font-size:32px}.source,.inspection .images,.controls,.grid{grid-template-columns:1fr}.inspection{padding:14px}.source{padding:12px}.card{padding:12px}}
</style></head><body><main><p class="meta">GOJŌ · CONCEPTS AS DECLARED STRUCTURAL READS</p><h1>One concept, different constructions</h1>
<p>A useful description should preserve what matters while admitting differences we deliberately leave open. Here the same native ornament is read through three contracts: its previous question vocabulary, its complete branch-and-route arrangement, and its individual sites and segments.</p>
<p class="meta"><a href="overview.html">Complete construction atlas</a> · <a href="diagnostics.json">Diagnostic comparisons</a> · <a href="concepts.gojo.json.gz">Native contracts and witnesses</a> · <a href="../../../../Gojo/docs/GojoOrnamentConceptEquivalence.md">Methods and findings</a> · <a href="../ornament-reconstruction/gallery.html">Previous reconstruction study</a></p>
<div class="stats" id="stats"></div><div class="controls">
<label>Reference construction<select id="source"></select></label>
<label>Question defining the current concept<select id="focus"><option value="branches">Same complete branch-and-route arrangement</option><option value="corners">Same topology including all intermediate sites</option><option value="legacy">Same answers to all 60 previous questions</option><option value="branches-legacy">Same branch-and-route arrangement AND previous answers</option></select></label>
<label>Display<select id="display"><option value="accepted">Supported examples</option><option value="all">All examples and near misses</option><option value="different">Supported, but different strict incidence</option><option value="vocabulary">Supported, but previous answers differ</option></select></label></div>
<div class="source"><div><h2 id="source-title"></h2><p id="source-note"></p><p class="note" id="source-facts"></p><img id="source-image" alt="Executed reference construction"></div><div><h2>What is promised here?</h2><p id="promise"></p><p id="contract-facts" class="notice"></p><p class="note">Unspecified is not false. This topology question does not promise equal petals, compass direction, colour, crossing order, or a planar inside/outside. Those need their own evidence and questions.</p></div></div>
<div class="example-buttons"><button data-example="different">Show a supported fan or window interpretation</button><button data-example="mechanics">Show changed construction history</button><button data-example="count">Show the extra-copy boundary</button><button data-example="rim">Show a missing-rim boundary</button><button data-example="unasked">Show an unasked arrangement distinction</button></div>
<div class="options"><label><input type="checkbox" id="groups"> Colour the actual drawing paths</label><span class="note">Colour explains execution groups; it does not mean Yes or No.</span></div>
<h2 id="results-title"></h2><p id="qualification" class="notice"></p><div class="grid" id="candidates"></div>
<section class="inspection" id="inspection" hidden><h2 id="inspect-title"></h2><div class="images"><img id="inspect-source" alt="Reference for this comparison"><img id="inspect-target" alt="Selected alternative construction"></div><p id="inspect-note"></p><div class="facts" id="inspect-facts"></div><p id="inspect-explanation" class="notice"></p><details open><summary>Questions whose answers differ</summary><p class="note">A different answer under a finer or differently focused question does not invalidate a supported coarse arrangement.</p><div class="scroll"><table><thead><tr><th>Previous question</th><th>Reference</th><th>Alternative</th></tr></thead><tbody id="disagreements"></tbody></table></div></details></section>
<details><summary>Where the preceding catalogue was too narrow</summary><p id="previous"></p><p>Matching all advertised questions gives an equivalence class for that vocabulary. The new branch-and-route contract instead declares a complete structural promise. Its accepted outputs may intentionally have different local shapes and drawing histories.</p></details>
<details><summary>Native encoding and boundaries of this experiment</summary><div id="limits"></div><p id="costs"></p><p class="note" id="verification"></p></details>
<p class="foot">Copper dots mark shared branch sites. Hollow violet marks mean different sites occupy one screen position. Rendered proportions are one uncalibrated interpretation. Every panel was generated through native programs and joins; pixels do not participate in these reads.</p>
</main><script src="data.js"></script><script>
const d=globalThis.ORNAMENT_CONCEPTS,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cases=new Map(d.cases.map(c=>[c.id,c])),pairs=new Map(d.pairs.map(p=>[p.source+'|'+p.target,p]));let selected=null;
const image=c=>$('groups').checked?c.groupImage:c.image;
const and=(a,b)=>a==='No'||b==='No'?'No':a==='Blocked'||b==='Blocked'?'Blocked':a==='Open'||b==='Open'?'Open':'Yes';
const answer=p=>$('focus').value==='branches-legacy'?and(p.branches,p.legacy):p[$('focus').value];
$('stats').innerHTML=`<span><strong>${d.counts.designs}</strong> executed constructions</span><span><strong>${d.counts.pairComparisons.toLocaleString()}</strong> source–target pairs</span><span><strong>${d.baseline.branches}</strong> reference arrangement matches</span><span><strong>${d.baseline.flexibleDifferentIncidence}</strong> with different strict incidence</span>`;
$('source').innerHTML=d.cases.map(c=>`<option value="${c.id}">${esc(c.id+' · '+c.name)}</option>`).join('');
const params=new URLSearchParams(location.search),requested=params.get('source');$('source').value=cases.has(requested)?requested:d.defaultSource;
const promises={branches:'Keep the whole connected arrangement of branch sites, loops and routes. A route may gain or lose intermediate degree-two sites: it can bend, stretch or be drawn in more steps. Every target segment must participate, so an extra branch, missing rim or extra disconnected copy cannot quietly disappear.',corners:'Keep a one-to-one topology of every published site and segment, including intermediate turning sites. Measured shape and headings remain outside this promise. This is a stricter structural question than the branch-and-route contract.',legacy:'Match the independently assessed answers to the 60 preceding motif, connection and mechanical-path questions. This is an assessed agreement class. It can miss distinctions none of those questions asks about.', 'branches-legacy':'Require both complete branch-and-route correspondence and agreement with the previous 60 questions. This retains the selected coarse arrangement while also preserving that particular vocabulary of local and mechanical evidence.'};
function render(){const source=cases.get($('source').value),current=d.pairs.filter(p=>p.source===source.id),self=pairs.get(source.id+'|'+source.id),focus=$('focus').value,view=$('display').value;
$('source-title').textContent=source.id+' · '+source.name;$('source-note').textContent=source.constructionNote;$('source-facts').textContent=`${source.sites} published sites · ${source.segments} segments · ${source.groups} drawing groups`;$('source-image').src=image(source);$('promise').textContent=promises[focus];
$('contract-facts').textContent=focus==='legacy'?`${d.queries.length} independently assessed questions; no whole-graph coverage is implied.`:`The compact native contract exposes ${self.sourceAnchors} retained landmarks and ${self.sourceRoutes} routes. The finer reference has ${source.sites} sites and ${source.segments} segments.`;
const admitted=current.filter(p=>answer(p)==='Yes'),shown=current.filter(p=>view==='all'||answer(p)==='Yes'&&(view==='accepted'||view==='different'&&p.incidence==='No'||view==='vocabulary'&&p.legacy==='No'));
$('results-title').textContent=`${admitted.length} supported constructions · showing ${shown.length}`;
$('qualification').textContent=focus==='legacy'?'These examples agree under the chosen 60 questions. That does not establish a complete concept definition: extra copies or arrangements can remain unasked.':`Supported means the declared complete arrangement is preserved. Visual difference is allowed within that promise. ${admitted.filter(p=>p.incidence==='No').length} supported examples differ under the separate strict incidence/heading read.`;
$('candidates').innerHTML=shown.length?shown.map(p=>{const c=cases.get(p.target),a=answer(p);return `<article class="card" tabindex="0" role="button" data-target="${c.id}" aria-label="Inspect ${esc(c.id+' '+c.name)}"><span class="pill">${a==='Yes'?'Supported':a==='No'?'Outside this contract':esc(a)}</span><h3>${esc(c.id+' · '+c.name)}</h3><img loading="lazy" src="${esc(image(c))}" alt="${esc(c.name)}"><p>${esc(c.constructionNote)}</p><div class="chips"><span class="chip">Routes: ${esc(p.branches)}</span><span class="chip">All sites: ${esc(p.corners)}</span><span class="chip comparison">Previous answers: ${esc(p.legacy)}</span><span class="chip comparison">Strict incidence: ${esc(p.incidence)}</span></div></article>`}).join(''):'<p class="empty">No construction meets this display filter. Try another question or show all examples.</p>';
for(const card of document.querySelectorAll('[data-target]')){card.onclick=()=>inspect(card.dataset.target,true);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect(card.dataset.target,true);}};}
if(selected)inspect(selected,false);
}
function inspect(id,scroll){selected=id;const source=cases.get($('source').value),target=cases.get(id),p=pairs.get(source.id+'|'+id);$('inspection').hidden=false;$('inspect-title').textContent=`${source.id} → ${id} · ${target.name}`;$('inspect-source').src=image(source);$('inspect-target').src=image(target);$('inspect-note').textContent=target.constructionNote;
$('inspect-facts').innerHTML=[['Current contract',answer(p)],['Previous 60 answers',p.legacy],['All-site topology',p.corners],['Strict incidence',p.incidence],['Ordered published relations',p.orderedRelations],['Native correspondence',p.correspondenceRows+' rows']].map(([a,b])=>`<span>${esc(a)}: <strong>${esc(b)}</strong></span>`).join('');
$('inspect-explanation').textContent=p.branches==='Yes'?`${p.sourceAnchors} source landmarks and ${p.sourceRoutes} routes cover the target's ${target.segments} segments through ${p.targetAnchors} landmarks and ${p.targetRoutes} routes. ${p.legacy==='No'?'The prior vocabulary notices different local or mechanical details. Those differences are outside this coarse contract.':p.incidence==='No'?'The strict graph differs; the selected route resolution deliberately leaves that detail open.':'This example also retains the finer topology.'}`:p.branches==='No'?'No complete branch-and-route correspondence exists under this contract. All target participation was considered; local resemblance alone cannot establish the missing whole arrangement.':'The arrangement read is unfinished or blocked. It is not counted as refuted simply to obtain a smaller set.';
$('disagreements').innerHTML=p.disagreements.length?p.disagreements.map(q=>`<tr><td>${esc(d.queries[q].label)}</td><td>${esc(source.answers[q])}</td><td>${esc(target.answers[q])}</td></tr>`).join(''):'<tr><td colspan="3">No settled answers differ under the previous vocabulary.</td></tr>';
if(scroll)$('inspection').scrollIntoView({behavior:'smooth',block:'start'});
}
for(const id of ['source','focus','display','groups'])$(id).addEventListener('change',render);
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{const source=cases.get($('source').value),preferred=['R37','R38','R14','R11'].map(id=>pairs.get(source.id+'|'+id)).find(p=>p.branches==='Yes'&&p.incidence==='No'&&p.target!==source.id);let p=preferred||d.pairs.find(p=>p.source===source.id&&p.branches==='Yes'&&p.incidence==='No'&&p.target!==source.id);let target=b.dataset.example==='mechanics'?'R21':b.dataset.example==='count'?'R23':b.dataset.example==='rim'?'R24':b.dataset.example==='unasked'?'R28':p?.target||'R11';inspect(target,true);});
$('previous').textContent=d.previousCatalogue.available?`The preceding catalogue had ${d.previousCatalogue.matches} outputs matching the reference's complete 60-answer vector, all from ${d.previousCatalogue.families.join(', ')}. They varied orientation, reach and independent copy count. This expanded corpus tests genuinely different path constructions and explicit near misses.`:'The previous catalogue was unavailable; this run still assesses all displayed native constructions independently.';
$('limits').innerHTML=d.limits.map(s=>`<p>${esc(s)}</p>`).join('');
$('costs').textContent=`The reference route contract uses ${cases.get(d.defaultSource).branchQuestionParticipants} native participants after crystallization, compared with ${cases.get(d.defaultSource).fineBranchQuestionParticipants} for the uncompressed template with the same route permissions. It is a source-free graph with a whole-cover promise. Its correspondence and discarded source detail stay outside the communicated root. These are structural counts, not bits, bytes or human conceptual units.`;
$('verification').textContent=`${d.counts.transportGraphs} independently regenerated native recipes preserved strict published graphs and ${d.counts.transportAnswers.toLocaleString()} query answers. ${d.counts.transportedQuestions} source-free contracts survived separate transport and admitted those fresh outputs. Assessment took ${d.counts.seconds.toFixed(1)} seconds; this includes prepared profiles and pair comparisons, not learned training.`;
render();if(cases.has(params.get('target')))inspect(params.get('target'),false);
</script></body></html>
""";

    private static string Overview() => """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ornament concepts · construction atlas</title><style>body{font:15px/1.45 system-ui;background:#faf8ee;color:#263d4e;margin:25px}h1,h2{font-family:Georgia;font-weight:400}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}article{background:#fffdf6;border:1px solid #cccebf;padding:13px}a{color:#315f79}img{width:100%;aspect-ratio:2;object-fit:contain}h2{font-size:21px}p{font-size:13px}@media(max-width:950px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:500px){.grid{grid-template-columns:1fr}}</style><h1>One concept, different constructions</h1><p><a href="gallery.html">Inspect concept contracts and alternatives</a>. This atlas includes supported alternatives and near misses; appearance or position in the atlas does not establish an admission.</p><div class="grid" id="atlas"></div><script src="data.js"></script><script>const d=globalThis.ORNAMENT_CONCEPTS;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));document.getElementById('atlas').innerHTML=d.cases.map(c=>`<article><h2>${esc(c.id+' · '+c.name)}</h2><a href="gallery.html?source=${encodeURIComponent(d.defaultSource)}&target=${encodeURIComponent(c.id)}"><img loading="lazy" src="${esc(c.image)}" alt="${esc(c.name)}"></a><p>${esc(c.constructionNote)}</p></article>`).join('');</script></html>
